import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// ---------- DATA ----------
const CHANNELS = [
  {
    handle: "@northwave.studio",
    avatarColor: "#FF4800",
    subs: 487_320,
    beforeRatio: 1.8,
    afterRatio: 5.4,
  },
  {
    handle: "@kairo.builds",
    avatarColor: "#F86606",
    subs: 612_445,
    beforeRatio: 2.1,
    afterRatio: 6.3,
  },
  {
    handle: "@mara.codes",
    avatarColor: "#FF6B2C",
    subs: 534_810,
    beforeRatio: 1.5,
    afterRatio: 4.5,
  },
];

function formatNumber(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(2) + "M";
  if (n >= 1_000) return (n / 1_000).toFixed(0) + "K";
  return n.toLocaleString("en-US");
}

// ---------- ICONS ----------
const PlayIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <rect x="2" y="5" width="20" height="14" rx="4" fill={color} />
    <path d="M10 9 L15 12 L10 15 Z" fill={COLORS.bg} />
  </svg>
);

const PersonIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="8" r="4" fill={color} />
    <path d="M4 21 C4 15.5, 8 13, 12 13 C16 13, 20 15.5, 20 21" fill={color} />
  </svg>
);

const ArrowUp: React.FC<{ size: number; color: string; progress: number }> = ({
  size,
  color,
  progress,
}) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path
      d="M12 20 L12 5 M5 12 L12 5 L19 12"
      stroke={color}
      strokeWidth={3}
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeDasharray={50}
      strokeDashoffset={interpolate(progress, [0, 1], [50, 0])}
    />
  </svg>
);

// ---------- CHANNEL CARD ----------
type Channel = (typeof CHANNELS)[number];

const ChannelCard: React.FC<{
  channel: Channel;
  index: number;
  delay: number;
}> = ({ channel, index, delay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const cardIn = springIn(frame, vfps, delay, "LIQUID");
  const avatarIn = springIn(frame, vfps, delay + 6, "ELASTIC");
  const subsIn = springIn(frame, vfps, delay + 10, "GENTLE");

  const beforeBarDelay = delay + 20;
  const beforeBarIn = springIn(frame, vfps, beforeBarDelay, "LIQUID");

  const tripleStart = delay + 50;
  const tripleProgress = spring({
    frame,
    fps: vfps,
    delay: tripleStart,
    config: SPRINGS.LIQUID,
  });

  const arrowIn = springIn(frame, vfps, tripleStart + 4, "ELASTIC");

  const driftY = ambientDrift(frame, 2, 90 + index * 11, `card-${index}-y`);
  const driftRot = ambientDrift(frame, 0.3, 130 + index * 7, `card-${index}-r`);

  const beforeWidthPct = channel.beforeRatio * 12;
  const afterWidthPct = beforeWidthPct * 3;

  const animatedWidth = interpolate(
    tripleProgress,
    [0, 1],
    [beforeWidthPct, afterWidthPct]
  );
  const barWidth = beforeBarIn * (tripleProgress < 0.01 ? beforeWidthPct : animatedWidth);

  const barColorMix = tripleProgress;

  const multiplier = interpolate(tripleProgress, [0, 1], [1, 3]);

  const beforeViews = Math.round(channel.subs * channel.beforeRatio);
  const afterViews = Math.round(channel.subs * channel.afterRatio);
  const currentViews = Math.round(
    interpolate(tripleProgress, [0, 1], [beforeViews, afterViews])
  );

  const cardTransform = `
    translateY(${interpolate(cardIn, [0, 1], [40, 0]) + driftY}px)
    rotate(${driftRot}deg)
    scale(${interpolate(cardIn, [0, 1], [0.94, 1])})
  `;

  return (
    <div
      style={{
        opacity: cardIn,
        transform: cardTransform,
        filter: `blur(${interpolate(cardIn, [0, 1], [6, 0])}px)`,
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 28,
        padding: "36px 40px",
        display: "flex",
        flexDirection: "column",
        gap: 26,
        boxShadow: `0 24px 64px rgba(0,0,0,0.5)`,
        width: "100%",
      }}
    >
      {/* Top row — avatar + handle/subs + multiplier */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 28,
        }}
      >
        {/* Avatar */}
        <div
          style={{
            opacity: avatarIn,
            transform: `scale(${interpolate(avatarIn, [0, 1], [0.5, 1])})`,
            width: 100,
            height: 100,
            borderRadius: "50%",
            background: `linear-gradient(135deg, ${channel.avatarColor}, ${COLORS.orangeDeep})`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
            boxShadow: `0 12px 32px rgba(248,102,6,0.35)`,
          }}
        >
          <PersonIcon size={56} color={COLORS.text} />
        </div>

        {/* Handle + subs */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
            flex: 1,
            minWidth: 0,
          }}
        >
          <div
            style={{
              opacity: avatarIn,
              transform: `translateX(${interpolate(avatarIn, [0, 1], [-16, 0])}px)`,
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 38,
              fontWeight: 700,
              color: COLORS.text,
              letterSpacing: "-0.02em",
              lineHeight: 1,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {channel.handle}
          </div>

          <div
            style={{
              opacity: subsIn,
              transform: `translateX(${interpolate(subsIn, [0, 1], [-12, 0])}px)`,
              display: "flex",
              alignItems: "center",
              gap: 10,
              fontFamily: "Inter, sans-serif",
            }}
          >
            <PersonIcon size={22} color={COLORS.textMuted} />
            <span
              style={{
                fontSize: 24,
                fontWeight: 600,
                color: COLORS.textMuted,
                fontVariantNumeric: "tabular-nums",
                fontFamily: "Inter, sans-serif",
              }}
            >
              {formatNumber(channel.subs)}
            </span>
            <span
              style={{
                fontSize: 22,
                color: COLORS.textSubtle,
                fontFamily: "Inter, sans-serif",
                fontWeight: 500,
              }}
            >
              subs
            </span>
          </div>
        </div>

        {/* Multiplier badge */}
        <div
          style={{
            opacity: arrowIn,
            transform: `scale(${interpolate(arrowIn, [0, 1], [0.6, 1])})`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 6,
            flexShrink: 0,
          }}
        >
          <ArrowUp size={36} color={COLORS.orange} progress={arrowIn} />
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 44,
              fontWeight: 800,
              color: COLORS.orange,
              letterSpacing: "-0.04em",
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
              background: COLORS.orangeTint,
              padding: "6px 16px",
              borderRadius: 12,
              border: `1.5px solid ${COLORS.orange}`,
            }}
          >
            {multiplier.toFixed(1)}x
          </div>
        </div>
      </div>

      {/* Bar row — views per sub visualization */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 14,
          opacity: beforeBarIn,
        }}
      >
        <PlayIcon
          size={28}
          color={barColorMix > 0.3 ? COLORS.orange : COLORS.textMuted}
        />

        <div
          style={{
            flex: 1,
            height: 28,
            background: "rgba(255,255,255,0.06)",
            borderRadius: 14,
            overflow: "hidden",
            position: "relative",
          }}
        >
          <div
            style={{
              width: `${barWidth}%`,
              height: "100%",
              borderRadius: 14,
              background:
                barColorMix < 0.05
                  ? COLORS.textSubtle
                  : `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.orangeDeep})`,
              boxShadow:
                barColorMix > 0.3
                  ? `0 0 24px rgba(248,102,6,${0.3 * barColorMix})`
                  : "none",
            }}
          />
        </div>

        <div
          style={{
            minWidth: 110,
            fontFamily: "Inter, sans-serif",
            fontSize: 24,
            fontWeight: 700,
            color: barColorMix > 0.3 ? COLORS.orange : COLORS.text,
            fontVariantNumeric: "tabular-nums",
            textAlign: "right",
          }}
        >
          {formatNumber(currentViews)}
        </div>
      </div>
    </div>
  );
};

// ---------- SCENE ----------
const ChannelsScene: React.FC = () => {
  const frame = useCurrentFrame();

  const stackDriftY = ambientDrift(frame, 3, 140, "stack-y");

  return (
    <AbsoluteFill
      style={{
        fontFamily: "Inter, sans-serif",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        transform: `translateY(${stackDriftY}px)`,
      }}
    >
      <div
        style={{
          width: "33.333%",
          display: "flex",
          flexDirection: "column",
          gap: 32,
        }}
      >
        {CHANNELS.map((channel, i) => (
          <ChannelCard
            key={channel.handle}
            channel={channel}
            index={i}
            delay={8 + i * 14}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ---------- COMPOSITION ----------
const SCENE_DURATION = 260;
export const durationInFrames = SCENE_DURATION;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_DURATION}>
        <ChannelsScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
